    def is_balanced(s: str) -> bool:
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    def separate(s: str) -> List[str]:
        result = []
        while '(' in s and ')' in s:
            i = s.index('(')
            j = s.index(')')
            if is_balanced(s[i:j+1]):
                result.append(s[i:j+1])
                s = s[:i] + s[j+1:]
        if '(' in s:
            result.append(s)
        return result

    return separate(paren_string.replace(' ', ''))

