def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    a, b = 0, 1
    i = 1
    while i < n:
        a, b = b, a + b
        i += 1
    return b if is_prime(b) else prime_fib(n)

